CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, login text UNIQUE NOT NULL, name text NOT NULL, avatar_url text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS github_identities (user_id uuid PRIMARY KEY REFERENCES users(id), github_id bigint UNIQUE NOT NULL, access_token_ciphertext bytea, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contribution_days (user_id uuid REFERENCES users(id), day date NOT NULL, contribution_count integer NOT NULL CHECK (contribution_count >= 0), contribution_level smallint NOT NULL CHECK (contribution_level BETWEEN 0 AND 4), PRIMARY KEY(user_id, day));
CREATE TABLE IF NOT EXISTS games (id uuid PRIMARY KEY, mode text NOT NULL CHECK(mode IN ('solo','pvp')), status text NOT NULL CHECK(status IN ('battle','complete')), current_turn text NOT NULL, winner text, player_id uuid NOT NULL REFERENCES users(id), player_start date NOT NULL, enemy_start date NOT NULL, state jsonb NOT NULL, terminal_applied boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mode_stats (user_id uuid REFERENCES users(id), mode text CHECK(mode IN ('solo','pvp')), games integer NOT NULL DEFAULT 0, wins integer NOT NULL DEFAULT 0, losses integer NOT NULL DEFAULT 0, rating integer NOT NULL DEFAULT 1200, shots integer NOT NULL DEFAULT 0, hits integer NOT NULL DEFAULT 0, current_streak integer NOT NULL DEFAULT 0, longest_streak integer NOT NULL DEFAULT 0, win_shots integer NOT NULL DEFAULT 0, PRIMARY KEY(user_id,mode));
CREATE TABLE IF NOT EXISTS challenges (id uuid PRIMARY KEY, code text UNIQUE NOT NULL, creator_game_id uuid REFERENCES games(id), opponent_id uuid REFERENCES users(id), status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS shares (id text PRIMARY KEY, game_id uuid UNIQUE NOT NULL REFERENCES games(id), created_at timestamptz NOT NULL DEFAULT now());

